-- by default using wfunc=hann + scale=linlog + delay=0.01 + zero_phase=0 + min_phase=0, 
-- you can tune e.g use blackmann/nuttall/bharris loglog zero_phase min_phase delay

-- this 4096 band, interpolation rebuilding from Local EQ a simple way
local function build_4096_from_anchor(anchor_str)
    local anchors = {}
    for f,g in anchor_str:gmatch("entry%(([%d%.]+),([%-%d%.]+)%)") do
        anchors[#anchors+1] = { tonumber(f), tonumber(g) }
    end

    local function interp(freq)
        for i = 1, #anchors-1 do
            local f0,g0 = anchors[i][1], anchors[i][2]
            local f1,g1 = anchors[i+1][1], anchors[i+1][2]
            if freq >= f0 and freq <= f1 then
                local t = (freq - f0) / (f1 - f0)
                return g0 + t * (g1 - g0)
            end
        end
        return anchors[#anchors][2]
    end
	
    local entries = {}
    local bands = 4094 -- reduced 2 band from 4096
    local fmin, fmax = 20, 20000

    for i = 0, bands-1 do
        local f = fmin * (fmax/fmin) ^ (i/(bands-1))
        local g = interp(f)
        entries[#entries+1] = string.format("entry(%.2f,%.2f)", f, g)
    end

    local tail = anchor_str:match('"([^"]*):wfunc=.+$') or 'min_phase=1' -- you can change to zero_phase
    return 'firequalizer=gain_entry="' .. table.concat(entries, ";") .. '":' .. tail
end

EQ.Techno_Harman_4096 		   = build_4096_from_anchor(EQ.Techno_Harman)
