local current = nil   -- eq1/eq2/EQname or nil
local enabled = false -- ON/OFF state

local function clear_all()
    pcall(function()
        mp.commandv("af", "remove", "@eq")
    end)
end

local function apply(eqname)
    current = eqname
    enabled = true
    clear_all()
    mp.commandv("af", "add", "@eq:" .. EQ[eqname])
    mp.osd_message("EQ: " .. eqname .. " (ON)")
end

local function toggle()
    if not current then
        mp.osd_message("No EQ selected")
        return
    end
    if enabled then
        clear_all()
        enabled = false
        mp.osd_message("EQ OFF")
    else
        mp.commandv("af", "add", "@eq:" .. EQ[current])
        enabled = true
        mp.osd_message("EQ ON (" .. current .. ")")
    end
end
-- EQ naming and key bindings can modified by yourself
