mp.register_script_message("soxr-ready", function()
    -- Re-apply EQ soxr after rebuild chain
    if current then
        mp.commandv("af", "add", "@eq:" .. EQ[current])
        enabled = true
        mp.osd_message("EQ: " .. current .. " (restored)", 2)
    end
end)

